//! MCP client management is a regular sandboxed Portable UI guest.
// Canonical ABI unsafe is generated by the frozen Bytecode Alliance generator.
// Handwritten application code is kept in a module with unsafe_code forbidden.
mod bindings {
    wit_bindgen::generate!({
        path: "../../../../specs/extensions/wit/mcp-runtime-v1",
        world: "runtime-v1",
        generate_all,
    });
    #[cfg(target_arch = "wasm32")]
    use super::management::Management;
    // Canonical ABI export names are Wasm symbols, not native ELF/Mach-O exports.
    // Keep generated types available to native unit tests and binding doctests.
    #[cfg(target_arch = "wasm32")]
    export!(Management with_types_in self);
}
#[cfg(any(target_arch = "wasm32", test))]
mod management;
